// Built-in labeled eval set (kept in sync with the 'SecOps triage eval set' Data Table).
return [
  { json: { alert_type: 'Ransomware encrypting multiple production servers; domain controller compromised; active data exfiltration', indicator: 'cobalt-strike-c2.ransom-gang.example', source: 'EDR - CrowdStrike Falcon (confirmed, multiple hosts)', expected_verdict: 'malicious', expected_severity: 'critical' } },
  { json: { alert_type: 'Outbound beacon to known Cobalt Strike C2 every 60s from a single workstation', indicator: '185.220.101.47', source: 'Zeek network sensor', expected_verdict: 'malicious', expected_severity: 'high' } },
  { json: { alert_type: 'User reported phishing email with a credential-harvesting link', indicator: 'https://secure-login-verify.example.com/o365', source: 'Email gateway - Proofpoint', expected_verdict: 'suspicious', expected_severity: 'medium' } },
  { json: { alert_type: 'Inbound TCP port scan across /24 from external IP', indicator: '198.51.100.23', source: 'Firewall - Palo Alto', expected_verdict: 'suspicious', expected_severity: 'low' } },
  { json: { alert_type: 'Scheduled vulnerability scan from the approved internal scanner', indicator: '10.20.0.15', source: 'Qualys scanner (allowlisted)', expected_verdict: 'benign', expected_severity: 'low' } },
];

const rows = $('Eval cases').all().map(i => i.json);
const outs = $input.all().map(i => i.json);
let v = 0, s = 0;
const detail = [];
for (let k = 0; k < rows.length; k++) {
  const exp = rows[k] || {};
  const got = (outs[k] && outs[k].output) ? outs[k].output : {};
  const vOk = got.verdict === exp.expected_verdict;
  const sOk = got.severity === exp.expected_severity;
  if (vOk) v++;
  if (sOk) s++;
  detail.push({
    alert: exp.alert_type,
    expected_verdict: exp.expected_verdict,
    actual_verdict: got.verdict ?? '(none)',
    verdict_ok: vOk ? 1 : 0,
    expected_severity: exp.expected_severity,
    actual_severity: got.severity ?? '(none)',
    severity_ok: sOk ? 1 : 0,
  });
}
const n = rows.length || 1;
const summary = {
  cases: rows.length,
  verdict_accuracy: Number((v / n).toFixed(2)),
  severity_accuracy: Number((s / n).toFixed(2)),
};
const report = `# SecOps triage eval\n\n**Cases:** ${summary.cases}  ·  **Verdict accuracy:** ${Math.round(summary.verdict_accuracy*100)}%  ·  **Severity accuracy:** ${Math.round(summary.severity_accuracy*100)}%\n\n` +
  detail.map(l => `- ${l.verdict_ok? '✅':'❌'} verdict / ${l.severity_ok? '✅':'❌'} severity — got ${l.actual_verdict}/${l.actual_severity}, expected ${l.expected_verdict}/${l.expected_severity} — ${String(l.alert||'').slice(0,60)}`).join('\n');
return [{ json: { summary, detail, report } }];
